#!/usr/bin/env python3
"""Generate dist/palettes.js from Omarchy's built-in colors.toml files."""
import json
import sys
import tomllib
from pathlib import Path

src = Path(sys.argv[1] if len(sys.argv) > 1 else Path.home() / ".local/share/omarchy/themes")
out = Path(__file__).resolve().parent.parent / "dist" / "palettes.js"

palettes = {}
for d in sorted(src.iterdir()):
    f = d / "colors.toml"
    if f.is_file():
        palettes[d.name] = tomllib.loads(f.read_text())

out.write_text(
    "// Generated by tools/gen-palettes.py from Omarchy colors.toml. Do not edit.\n"
    "window.OMARCHY_PALETTES = " + json.dumps(palettes, indent=1) + ";\n"
)
print(f"{len(palettes)} palettes -> {out}")
